ei?","Ich bestelle eine Pizza."],["practice","Welche Aussage gehört zu diesem Dialog?","Nur Aufgabe zwei?","Wo ist die Treppe?","Der Zug fährt um sieben Uhr."],["practice","Welche Antwort folgt logisch?","Ja, nur Aufgabe zwei.","Entschuldigung, wo ist die Klasse 1B?","Ich möchte eine Jacke kaufen."],["grammar","Was ist richtig?","Heute ist mein erster Schultag.","Heute heute ist mein erster schultag.","Nicht korrekt: Verb fehlt."],["grammar","Im Hauptsatz steht das konjugierte Verb meistens ...","an Position 2","immer am Ende","immer an Position 1"],["grammar","Welche Form ist ein normaler Aussagesatz?","Entschuldigung, wo ist das Sekretariat?","Verb Satz ohne Struktur.","Nur Nomen."],["grammar","Welche Aussage ist vollständig?","Der Unterricht ist um zwölf Uhr aus.","Nur ein Stichwort.","Ohne Verb."],["grammar","Welches Fragewort fragt nach einem Ort?","Wo","Wann","Was"],["grammar","Welches Fragewort fragt nach einer Zeit?","Wann","Wo","Wer"],["grammar","Welches Fragewort fragt nach einer Sache/Information?","Was","Wo","Wie alt"],["grammar","Welche Frage passt am besten zum Thema?","Wo ist der Eingang?","Wie teuer ist ein Auto?","Wo ist das Schwimmbad?"],["grammar","Welche zweite Frage passt ebenfalls?","Entschuldigung, wo ist das Sekretariat?","Welche Farbe hat das Wetter?","Wie groß ist die Bank?"],["grammar","Bei einer Ja-/Nein-Frage steht das Verb meistens ...","am Anfang","immer am Ende","gar nicht im Satz"],["grammar","Welche Form ist eine Ja-/Nein-Frage?","Wo ist der Eingang?","Wo ist der Raum?","Welche Seite?"],["grammar","Welche kurze Antwort passt?","Ja, bitte.","Auf Seite 14.","Im ersten Stock."],["grammar","Was ist höflich?","Entschuldigung, wo ist das Sekretariat?","Sofort!","Du jetzt!"],["grammar","Welche Form ist eine höfliche Anweisung?","Bitte nehmen Sie das Arbeitsblatt.","Du sofort!","Kein Verb."],["grammar","Welche Form passt zur Sie-Anrede?","Schreiben Sie bitte Ihren Namen oben.","Öffnest du Buch.","Buch öffnen du."],["grammar","Was macht „bit